const USERS = { 1: { id: 1, name: 'Ada' } };
const ORDERS = { 1: [{ amount: 10 }, { amount: 20 }] };

function fetchUser(id) {
  return new Promise((resolve, reject) => {
    setImmediate(() => (USERS[id] ? resolve(USERS[id]) : reject(new Error('no such user'))));
  });
}

function fetchOrders(userId) {
  return new Promise((resolve) => setImmediate(() => resolve(ORDERS[userId] || [])));
}

function summarize(user, orders) {
  return Promise.resolve({
    name: user.name,
    orderCount: orders.length,
    total: orders.reduce((s, o) => s + o.amount, 0),
  });
}

module.exports = { fetchUser, fetchOrders, summarize };

