const { fetchUser, fetchOrders, summarize } = require('./steps.js');

function buildSummary(userId) {
  return fetchUser(userId).then((user) =>
    fetchOrders(user.id).then((orders) => summarize(user, orders))
  );
}

module.exports = { buildSummary };

