const assert = require('node:assert');
const { buildSummary } = require('./pipeline.js');

(async () => {
  const summary = await buildSummary(1);
  assert.deepStrictEqual(summary, { name: 'Ada', orderCount: 2, total: 30 });

  // a rejection must propagate, not be swallowed
  await assert.rejects(() => buildSummary(999), /no such user/);

  console.log('ok');
})().catch((err) => {
  console.error(err);
  process.exit(1);
});

