const { fetchUser, fetchOrders, summarize } = require('./steps.js');

async function buildSummary(userId) {
  // DRIFT: a try/catch swallows step errors and resolves null instead of
  // propagating the rejection.
  try {
    const user = await fetchUser(userId);
    const orders = await fetchOrders(user.id);
    return await summarize(user, orders);
  } catch (err) {
    return null;
  }
}

module.exports = { buildSummary };
